loginUrl:
@js:
function login() {}

function gengxin() {
    java.toast('正在检查...');
    var r = java.get('https://cdn.jsdelivr.net/gh/fengying915/yuedu@main/订阅/源社区.json', {
        'User-Agent': 'Mozilla/5.0'
    }).body();
    var d = JSON.parse(r)[0];
    var rb = d.jsLib.match(/banben="([^"]+)"/)[1];
    var gxts;
    if (rb != banben) {
        gxts = ['有更新', '0,140,186'];
    } else {
        gxts = ['已是最新', '76,175,80'];
    }
    var h = '<html>'
        + '<body style="font-size:24px;text-align:center;padding:20px;background:linear-gradient(135deg,#667eea,#764ba2);min-height:100vh;display:flex;align-items:center;justify-content:center;">'
        + '<div style="background:white;border-radius:20px;padding:40px;max-width:400px;width:100%;box-shadow:0 20px 60px rgba(0,0,0,0.3);">'
        + '<div style="font-size:72px;">📦</div>'
        + '<h2 style="font-size:30px;margin:20px 0;">版本检测</h2>'
        + '<div style="display:inline-block;padding:10px 24px;border-radius:20px;color:white;font-size:22px;background:rgb(' + gxts[1] + ')">' + gxts[0] + '</div>'
        + '<p style="margin:18px 0;">本地: V' + banben + '</p>'
        + '<p style="margin:18px 0;">仓库: V' + rb + '</p>'
        + '<a href="legado://import/importonline?src=https://cdn.jsdelivr.net/gh/fengying915/yuedu@main/订阅/源社区.json" style="display:block;padding:20px;background:linear-gradient(135deg,#667eea,#764ba2);color:white;text-decoration:none;border-radius:12px;margin-top:24px;font-size:24px;font-weight:bold;">更新订阅源</a>'
        + '</div>'
        + '</body>'
        + '</html>';
    java.startBrowser('data:text/html;base64,' + java.base64Encode(h), '版本检测');
}
